BASE_DELAY_MS = 250

import time

class ThrottlingError(Exception):
    pass

def with_backoff(op, attempts=4):
    delay = BASE_DELAY_MS
    for _ in range(attempts):
        try:
            return op()
        except ThrottlingError:
            time.sleep(delay / 1000)
            delay = delay * 2
    raise ThrottlingError("giving up")
